213	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
214	// stars move faster. Returns its own teardown. Ported from the approved
215	// prototype so the shipped page matches it exactly.
216	function startDrift(canvas: HTMLCanvasElement): () => void {
217	  const ctx = canvas.getContext("2d");
218	  if (ctx === null) return () => {};
219	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
220	  let w = 0;
221	  let h = 0;
222	  let raf = 0;
223	  let stars: Star[] = [];
224	
225	  function size() {
226	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
227	    w = canvas.clientWidth;
228	    h = canvas.clientHeight;
229	    canvas.width = w * dpr;
230	    canvas.height = h * dpr;
231	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
232	  }
233	
234	  function build() {
235	    size();
236	    const count = Math.min(300, Math.floor((w * h) / 3600));
237	    stars = [];
238	    for (let i = 0; i < count; i++) {
239	      const depth = Math.random();
240	      stars.push({
241	        x: Math.random() * w,
242	        y: Math.random() * h,
243	        size: 0.5 + depth * 1.6,
244	        base: 0.1 + depth * 0.45,
245	        sp: 0.05 + depth * 0.22,
246	        tw: Math.random() * 6.28,
247	        hot: Math.random() < 0.04,
248	      });
249	    }
250	  }
251	
252	  function frame(t: number) {
253	    const time = t / 1000;
254	    ctx!.clearRect(0, 0, w, h);
255	    for (const s of stars) {
256	      if (!reduce) {
257	        s.x += s.sp;
258	        if (s.x > w + 2) s.x = -2;
259	      }
260	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
261	      ctx!.beginPath();
262	      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
263	      if (s.hot) {
264	        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
265	        ctx!.shadowColor = "rgba(10,132,255,.8)";
266	        ctx!.shadowBlur = 6;
267	      } else {
268	        ctx!.fillStyle = `rgba(255,255,255,${s.base * tw})`;
269	        ctx!.shadowBlur = 0;
270	      }
271	      ctx!.fill();
272	    }
273	    ctx!.shadowBlur = 0;
274	    if (!reduce) raf = requestAnimationFrame(frame);
275	  }
276	
277	  function onResize() {
278	    build();
279	    if (reduce) frame(0);
280	  }
281	
282	  build();
283	  if (reduce) frame(0);
284	  else raf = requestAnimationFrame(frame);
285	  window.addEventListener("resize", onResize);
286	
287	  return () => {
288	    cancelAnimationFrame(raf);
289	    window.removeEventListener("resize", onResize);
290	  };
291	}
